await $test.run("Fires for a click on a matching element", async () => {
  const sleep = $test.sleep;
  const root = document.createElement('div');
  root.innerHTML = '<button class="b">One</button>';
  const got = [];
  delegate(root, '.b', 'click', (e, el) => got.push(el.textContent));
  root.querySelector('.b').dispatchEvent(new MouseEvent('click', { bubbles: true }));
  return (got);
}, () => (['One']));

await $test.run("A click on a child of the match still counts (closest)", async () => {
  const sleep = $test.sleep;
  const root = document.createElement('div');
  root.innerHTML = '<button class="b"><span>One</span></button>';
  const got = [];
  delegate(root, '.b', 'click', (e, el) => got.push(el.tagName));
  root.querySelector('span').dispatchEvent(new MouseEvent('click', { bubbles: true }));
  return (got);
}, () => (['BUTTON']));

await $test.run("Non-matching targets are ignored", async () => {
  const sleep = $test.sleep;
  const root = document.createElement('div');
  root.innerHTML = '<button class="b">One</button><p>text</p>';
  const got = [];
  delegate(root, '.b', 'click', () => got.push('hit'));
  root.querySelector('p').dispatchEvent(new MouseEvent('click', { bubbles: true }));
  return (got);
}, () => ([]));

await $test.run("Elements added after delegate() are handled", async () => {
  const sleep = $test.sleep;
  const root = document.createElement('div');
  const got = [];
  delegate(root, '.b', 'click', (e, el) => got.push(el.id));
  const late = document.createElement('button');
  late.className = 'b';
  late.id = 'late';
  root.append(late);
  late.dispatchEvent(new MouseEvent('click', { bubbles: true }));
  return (got);
}, () => (['late']));

await $test.run("The returned function removes the listener", async () => {
  const sleep = $test.sleep;
  const root = document.createElement('div');
  root.innerHTML = '<button class="b">One</button>';
  const got = [];
  const off = delegate(root, '.b', 'click', () => got.push('hit'));
  off();
  root.querySelector('.b').dispatchEvent(new MouseEvent('click', { bubbles: true }));
  return (got);
}, () => ([]));

await $test.run("Matches outside the root are ignored", async () => {
  const sleep = $test.sleep;
  const outer = document.createElement('div');
  outer.className = 'b';
  const root = document.createElement('div');
  root.innerHTML = '<p>inside</p>';
  outer.append(root);
  const got = [];
  delegate(root, '.b', 'click', () => got.push('hit'));
  root.querySelector('p').dispatchEvent(new MouseEvent('click', { bubbles: true }));
