}, () => ([]));

await $test.run("Nested matches: the nearest one is used, once", async () => {
  const sleep = $test.sleep;
  const root = document.createElement('div');
  root.innerHTML = '<div class="item" id="outer"><div class="item" id="inner"><i>x</i></div></div>';
  const got = [];
  delegate(root, '.item', 'click', (e, el) => got.push(el.id));
  root.querySelector('i').dispatchEvent(new MouseEvent('click', { bubbles: true }));
  return (got);
}, () => (['inner']));

await $test.run("`this` is the matched element too", async () => {
  const sleep = $test.sleep;
  const root = document.createElement('div');
  root.innerHTML = '<button class="b" id="x">One</button>';
  let seen;
  delegate(root, '.b', 'click', function () { seen = this.id; });
  root.querySelector('.b').dispatchEvent(new MouseEvent('click', { bubbles: true }));
  return (seen);
