await $test.run("set then get returns the JSON value", async () => {
  const sleep = $test.sleep;
  const memory = () => { const m = new Map(); return { getItem: (k) => (m.has(k) ? m.get(k) : null), setItem: (k, v) => { m.set(k, v); }, removeItem: (k) => { m.delete(k); }, key: (i) => [...m.keys()][i] ?? null, get length() { return m.size; }, raw: m }; };
  const store = createStorage(memory());
  store.set('user', { name: 'Ada', tags: ['x'] });
  return (store.get('user'));
}, () => ({ name: 'Ada', tags: ['x'] }));

await $test.run("Missing key returns the fallback", async () => {
  const sleep = $test.sleep;
  const memory = () => { const m = new Map(); return { getItem: (k) => (m.has(k) ? m.get(k) : null), setItem: (k, v) => { m.set(k, v); }, removeItem: (k) => { m.delete(k); }, key: (i) => [...m.keys()][i] ?? null, get length() { return m.size; }, raw: m }; };
  const store = createStorage(memory());
  return ([store.get('nope'), store.get('nope', 'dflt')]);
}, () => ([null, 'dflt']));

await $test.run("An entry is available until its TTL, then it expires and is removed", async () => {
  const sleep = $test.sleep;
  const memory = () => { const m = new Map(); return { getItem: (k) => (m.has(k) ? m.get(k) : null), setItem: (k, v) => { m.set(k, v); }, removeItem: (k) => { m.delete(k); }, key: (i) => [...m.keys()][i] ?? null, get length() { return m.size; }, raw: m }; };
  let t = 1000;
  const backend = memory();
  const store = createStorage(backend, { now: () => t });
  store.set('k', 'v', { ttlMs: 500 });
  const fresh = store.get('k');
  t = 1600;
  return ([fresh, store.get('k', 'gone'), backend.length]);
}, () => (['v', 'gone', 0]));

