await $test.run("Elements already inside root are reported immediately, in document order", async () => {
  const sleep = $test.sleep;
  const el = (tag, children = [], id = tag) => {
    const node = {
      nodeType: 1, tag, id, children,
      matches: (s) => s === tag,
      querySelectorAll: (s) => {
        const out = [];
        const walk = (n) => n.children.forEach((child) => { if (child.tag === s) out.push(child); walk(child); });
        walk(node);
        return out;
      },
    };
    return node;
  };
  const text = () => ({ nodeType: 3 });
  const observers = [];
  class FakeMO {
    constructor(callback) { this.callback = callback; this.disconnected = false; observers.push(this); }
    observe(target, options) { this.target = target; this.options = options; }
    disconnect() { this.disconnected = true; }
